const cardIpa=Object.freeze({
  "a1-verbs-close": "/kloʊz/",
  "a4-rules-permit": "/pərˈmɪt/ · /ˈpɝmɪt/"
});

function wordIpa(word){
  const key=normalizeWord(word.en);
  return word.ipa||(Object.hasOwn(cardIpa,word.id)?cardIpa[word.id]:'')||(Object.hasOwn(builtInIpa,key)?builtInIpa[key]:'')||pronunciationCache.get('en:'+key)?.ipa||'';
}
function wordIpaMarkup(word){
  const ipa=wordIpa(word);
  return '<span class="word-ipa" lang="en"'+(ipa?'':' data-ipa-word="'+escapeHTML(word.en)+'"')+'>'+escapeHTML(ipa||'…')+'</span>';
}
const pendingIpa=new Map();
async function hydrateWordIpa(root){
  const queue=[...root.querySelectorAll('[data-ipa-word]')];
  async function worker(){while(queue.length){
    const node=queue.shift();if(!node.isConnected)continue;
    const term=normalizeWord(node.dataset.ipaWord);
    let result=null;
    if(validEnglishWord(term)){
      if(!pendingIpa.has(term))pendingIpa.set(term,pronunciationWord(term,'en').catch(()=>null).finally(()=>pendingIpa.delete(term)));
      result=await pendingIpa.get(term);
    }
    if(node.isConnected)node.textContent=result?.ipa||'Транскрипція недоступна';
  }}
  await Promise.all([worker(),worker(),worker()]);
}
